with open("data/funnel-model.csv","w",newline="") as f:
    w = csv.writer(f); w.writerow(["scenario","visits","start_rate","starts","completion_rate","completions","lead_rate","leads","review_rate","reviews_held","close_rate","new_client_projects","lead_to_client_pct"])
    for n,a in sc.items():
        st=a["v"]*a["s"]; co=st*a["c"]; le=co*a["l"]; rv=le*a["b"]; cl=rv*a["w"]
        w.writerow([n,a["v"],a["s"],round(st),a["c"],round(co),a["l"],round(le),a["b"],round(rv),a["w"],round(cl),round(cl/le*100,1)])
print("Built", len(rows), "evidence rows and 3 funnel scenarios")
